-- Pair 30 gallery for the owner: the pure part (no engine calls), shared by admin/actions_pack30_gallery.lua and
-- tests/pack30_gallery_test.lua.
--   parse      the `what` + `arg` of the admin action / talkaction into a command table
--   units      the generated lib (data/lib/chaos_pack30_items.lua) into placeable units (single items, whole groups)
--   layout     rows of units east of the admin, a strip of ground tiles, rows of looks, effect and missile rows
--   store      what was placed per admin (for `clear`), with the 30 minute expiry
-- The lib is generated by server/tools/install_pack30_items.py --lua and may be missing: every function accepts nil.
-- Lib shape read here (the numbers are server ids, client id + 3000):
--   items  = {key = {id=, w=, h=, kind=, block=, animated=, name=, group=}  (or key = id)}
--   groups = {name = {gw=, gh=, pieces = {{key=, r=, c=}, ...}}}          (piece=r,c is row, column of the piece grid)
--   schemes = {[lookType] = {{name=, head=, body=, legs=, feet=}, ...}}    (optional, the tint schemes)
-- Lua 5.1 / LuaJIT and Lua 5.3 compatible.

ChaosPack30GalleryCore = ChaosPack30GalleryCore or {}
local G = ChaosPack30GalleryCore

local floor = math.floor

G.MAX_OBJECTS = 150          -- objects (items, monsters) per call
G.TTL_MS = 30 * 60 * 1000    -- auto clear
G.ROW_TILES = 30             -- width of an item row before it wraps
G.LOOKS_PER_ROW = 8
G.LOOK_STEP = 3              -- tiles between two looks (a 2x2 look needs room)
G.GROUND_PER_ROW = 16
G.FX_STEP_MS = 1200
G.FX_MAX = 60
G.WEAR_MS = 10 * 60 * 1000
G.OFFSET_X = 2               -- first column east of the admin

-- Client id blocks of PLAN_PAIR30 section 2 (server id = client id + 3000).
G.BLOCKS = {
	["items-a"] = {34443, 34698}, ["items-b"] = {34699, 34718}, ["items-c"] = {34719, 34738}, ["items-d"] = {34739, 34758},
	["corpses-1"] = {34759, 34833}, ["corpses-2"] = {34834, 34858}, grounds = {34859, 35158},
	["decor-1"] = {35159, 35558}, ["decor-2"] = {35559, 36058}, bldg = {36059, 36458}, anim = {36459, 36000 + 758},
	reserve = {36000 + 759, 36999},
}
G.SERVER_OFFSET = 3000

-- a neutral scheme set for `schemes <look>` when the lib has no tint schemes of the look (outfit palette indexes)
G.DEFAULT_SCHEMES = {
	{name = "plain", head = 0, body = 0, legs = 0, feet = 0},
	{name = "red", head = 94, body = 94, legs = 79, feet = 79},
	{name = "green", head = 78, body = 78, legs = 58, feet = 58},
	{name = "blue", head = 88, body = 88, legs = 86, feet = 86},
	{name = "gold", head = 79, body = 76, legs = 114, feet = 114},
	{name = "violet", head = 133, body = 133, legs = 85, feet = 85},
	{name = "ash", head = 1, body = 1, legs = 114, feet = 114},
}

local function trim(s) return (tostring(s or ""):gsub("^%s+", ""):gsub("%s+$", "")) end

-- ------------------------------------------------------------------ parsing
-- "100-200" -> 100, 200; "100" -> 100, 100; nil when it is not a number range. Swapped bounds are put right.
function G.parseRange(s)
	s = trim(s)
	local a, b = s:match("^(%d+)%s*%-%s*(%d+)$")
	if not a then a = s:match("^(%d+)$"); b = a end
	if not a then return nil end
	a, b = tonumber(a), tonumber(b)
	if a > b then a, b = b, a end
	return a, b
end

-- command table: {cmd = "items", from =, to =, block =} | {cmd = "looks", from, to} | {cmd = "schemes", look} |
-- {cmd = "wear", look, scheme} | {cmd = "fx", from, to} | {cmd = "groups"|"grounds"|"anim"|"missiles"|"clear"}; nil, why.
function G.parse(what, arg)
	what = trim(what):lower()
	arg = trim(arg)
	if what == "" then return nil, "Say what to show (items, groups, grounds, anim, looks, schemes, fx, missiles, wear, clear)." end
	-- the talkaction passes everything in one string
	local w2, rest = what:match("^(%a+)%s+(.+)$")
	if w2 then what = w2; if arg == "" then arg = rest end end
	if what == "groups" or what == "grounds" or what == "anim" or what == "missiles" or what == "clear" then
		return {cmd = what}
	elseif what == "items" then
		if arg == "" then return nil, "items needs a block (" .. G.blockNames() .. ") or a client id range from-to." end
		local blk = G.BLOCKS[arg:lower()]
		if blk then return {cmd = "items", from = blk[1], to = blk[2], block = arg:lower()} end
		local a, b = G.parseRange(arg)
		if not a then return nil, "Unknown block '" .. arg .. "'. Blocks: " .. G.blockNames() .. "." end
		return {cmd = "items", from = a, to = b}
	elseif what == "looks" or what == "fx" then
		local a, b = G.parseRange(arg)
		if not a then return nil, what .. " needs a range from-to." end
		return {cmd = what, from = a, to = b}
	elseif what == "schemes" then
		local look = tonumber(arg)
		if not look or look < 1 then return nil, "schemes needs a look id." end
		return {cmd = "schemes", look = floor(look)}
	elseif what == "wear" then
		local l, s = arg:match("^(%d+)%s*(%d*)$")
		if not l then return nil, "wear needs a look id and optionally a scheme number." end
		return {cmd = "wear", look = tonumber(l), scheme = s ~= "" and tonumber(s) or nil}
	end
	return nil, "Unknown gallery command '" .. what .. "'."
end

function G.blockNames()
	local names = {}
	for n in pairs(G.BLOCKS) do names[#names + 1] = n end
	table.sort(names)
	return table.concat(names, ", ")
end

-- ------------------------------------------------------------------ units out of the lib
local function entryOf(key, v)
	if type(v) == "number" then return {key = key, id = v, w = 1, h = 1} end
	if type(v) ~= "table" or not tonumber(v.id) then return nil end
	return {key = key, id = tonumber(v.id), w = tonumber(v.w) or 1, h = tonumber(v.h) or 1, kind = v.kind, block = v.block,
		animated = v.animated and true or false, name = v.name, group = v.group}
end

-- every entry of the lib as a sorted list (by id, then key), nil-safe
function G.entries(lib)
	local out = {}
	for key, v in pairs((lib or {}).items or {}) do
		local e = entryOf(key, v)
		if e then out[#out + 1] = e end
	end
	table.sort(out, function(a, b) if a.id ~= b.id then return a.id < b.id end return a.key < b.key end)
	return out
end

local function clientId(e) return e.id - G.SERVER_OFFSET end

-- entries whose client id lies in from..to (ids above 37000+ are taken as server ids when both bounds are)
function G.selectRange(entries, from, to)
	local out = {}
	local serverMode = from >= 37443
	for _, e in ipairs(entries) do
		local v = serverMode and e.id or clientId(e)
		if v >= from and v <= to then out[#out + 1] = e end
	end
	return out
end

function G.selectGrounds(entries)
	local out = {}
	local blk = G.BLOCKS.grounds
	for _, e in ipairs(entries) do
		local c = clientId(e)
		if e.kind == "ground" or e.kind == "border" or (e.kind == nil and c >= blk[1] and c <= blk[2]) then out[#out + 1] = e end
	end
	return out
end

function G.selectAnim(entries)
	local out = {}
	local blk = G.BLOCKS.anim
	for _, e in ipairs(entries) do
		local c = clientId(e)
		if e.animated or (c >= blk[1] and c <= blk[2]) then out[#out + 1] = e end
	end
	return out
end

-- Placeable units: a single item {key, parts = {{key, id, w, h, ox, oy}}, w, h} where ox, oy is the tile of the part's
-- south-east corner inside the unit (an item of w x h tiles is drawn up and to the left of its own tile). A group
-- gets all its pieces at their r,c grid positions, so a building shows whole. `selected` is a list of entries; a
-- selected piece pulls in its whole group (once). With selected == nil every group of the lib is a unit.
function G.groupUnit(name, grp, lib)
	local pieces, colW, rowH, maxR, maxC = {}, {}, {}, 0, 0
	for _, p in ipairs(grp.pieces or {}) do
		local r, c = tonumber(p.r or p[2]) or 0, tonumber(p.c or p[3]) or 0
		local key = p.key or p[1]
		local e = entryOf(key, ((lib or {}).items or {})[key])
		if e then
			pieces[#pieces + 1] = {e = e, r = r, c = c}
			if r > maxR then maxR = r end
			if c > maxC then maxC = c end
			if (colW[c] or 0) < e.w then colW[c] = e.w end
			if (rowH[r] or 0) < e.h then rowH[r] = e.h end
		end
	end
	if #pieces == 0 then return nil end
	-- cumulative end tile (exclusive) of each column and row
	local colEnd, rowEnd, x, y = {}, {}, 0, 0
	for c = 0, maxC do x = x + (colW[c] or 0); colEnd[c] = x end
	for r = 0, maxR do y = y + (rowH[r] or 0); rowEnd[r] = y end
	table.sort(pieces, function(a, b) if a.r ~= b.r then return a.r < b.r end return a.c < b.c end)
	local unit = {key = name, group = true, w = x, h = y, parts = {}}
	for _, p in ipairs(pieces) do
		unit.parts[#unit.parts + 1] = {key = p.e.key, id = p.e.id, w = p.e.w, h = p.e.h, name = p.e.name,
			ox = colEnd[p.c] - 1, oy = rowEnd[p.r] - 1}
	end
	return unit
end

function G.groupOf(lib)
	local map = {}
	for name, grp in pairs((lib or {}).groups or {}) do
		for _, p in ipairs(grp.pieces or {}) do map[p.key or p[1]] = name end
	end
	for key, v in pairs((lib or {}).items or {}) do
		if type(v) == "table" and v.group and not map[key] and lib.groups and lib.groups[v.group] then map[key] = v.group end
	end
	return map
end

function G.units(lib, selected)
	local out, done = {}, {}
	local pieceGroup = G.groupOf(lib)
	if selected == nil then
		local names = {}
		for name in pairs((lib or {}).groups or {}) do names[#names + 1] = name end
		table.sort(names)
		for _, name in ipairs(names) do
			local u = G.groupUnit(name, lib.groups[name], lib)
			if u then out[#out + 1] = u end
		end
		return out
	end
	for _, e in ipairs(selected) do
		local gname = pieceGroup[e.key]
		if gname then
			if not done[gname] then
				done[gname] = true
				local u = G.groupUnit(gname, lib.groups[gname], lib)
				if u then out[#out + 1] = u end
			end
		else
			out[#out + 1] = {key = e.key, w = e.w, h = e.h, parts = {{key = e.key, id = e.id, w = e.w, h = e.h, name = e.name, ox = e.w - 1, oy = e.h - 1}}}
		end
	end
	return out
end

-- ------------------------------------------------------------------ layout
-- Rows of units east of `origin` (the admin): cell = unit size + 1 tile gap, wrap after ROW_TILES. Returns
-- {placements = {{x,y,z,id,key,name,unit}}, units = n, skippedUnits = n (cut by the object cap), rows = n}.
function G.layoutUnits(units, origin, opts)
	opts = opts or {}
	local cap = opts.max or G.MAX_OBJECTS
	local rowTiles = opts.rowTiles or G.ROW_TILES
	local out, used, skipped = {}, 0, 0
	local cx, cy, rowH, rows, placed = 0, 0, 0, 1, 0
	for _, u in ipairs(units or {}) do
		if used + #u.parts > cap then
			skipped = skipped + 1
		else
			if cx > 0 and cx + u.w > rowTiles then
				cx = 0; cy = cy + rowH + 1; rowH = 0; rows = rows + 1
			end
			for _, p in ipairs(u.parts) do
				out[#out + 1] = {x = origin.x + G.OFFSET_X + cx + p.ox, y = origin.y + cy + p.oy, z = origin.z, id = p.id, key = p.key,
					name = p.name, unit = u.key}
			end
			used = used + #u.parts
			placed = placed + 1
			cx = cx + u.w + 1
			if u.h > rowH then rowH = u.h end
		end
	end
	return {placements = out, units = placed, skippedUnits = skipped, rows = rows}
end

-- A strip of ground tiles (contiguous, GROUND_PER_ROW per row, one blank row between rows) at origin.y + 2 so the
-- admin keeps standing on his own tile. {placements = {{x,y,z,id,key}}, skipped = n}
function G.layoutGrounds(entries, origin, opts)
	opts = opts or {}
	local cap = opts.max or G.MAX_OBJECTS
	local per = opts.perRow or G.GROUND_PER_ROW
	local out = {}
	for i, e in ipairs(entries or {}) do
		if i > cap then break end
		local col, row = (i - 1) % per, floor((i - 1) / per)
		out[#out + 1] = {x = origin.x + G.OFFSET_X + col, y = origin.y + 2 + row * 2, z = origin.z, id = e.id, key = e.key, name = e.name}
	end
	return {placements = out, skipped = math.max(0, #(entries or {}) - cap)}
end

-- Looks in rows of 8, LOOK_STEP tiles apart. ids is a list of look types (or {look=, head=...} tables).
function G.layoutLooks(ids, origin, opts)
	opts = opts or {}
	local cap = opts.max or G.MAX_OBJECTS
	local per = opts.perRow or G.LOOKS_PER_ROW
	local out = {}
	for i, v in ipairs(ids or {}) do
		if i > cap then break end
		local col, row = (i - 1) % per, floor((i - 1) / per)
		local o = type(v) == "table" and v or {look = v}
		out[#out + 1] = {x = origin.x + G.OFFSET_X + col * G.LOOK_STEP, y = origin.y + row * G.LOOK_STEP, z = origin.z, look = o.look,
			head = o.head or 0, body = o.body or 0, legs = o.legs or 0, feet = o.feet or 0, label = o.label}
	end
	return {placements = out, skipped = math.max(0, #(ids or {}) - cap)}
end

function G.range(from, to, cap)
	local out = {}
	for v = from, math.min(to, from + (cap or G.MAX_OBJECTS) - 1) do out[#out + 1] = v end
	return out
end

-- Tint schemes of a look: the lib's, else the default set.
function G.schemesOf(lib, look)
	local s = ((lib or {}).schemes or {})[look]
	if type(s) == "table" and #s > 0 then return s, true end
	return G.DEFAULT_SCHEMES, false
end

-- `schemes <look>`: one look per scheme, named in the label.
function G.layoutSchemes(lib, look, origin)
	local list = G.schemesOf(lib, look)
	local ids = {}
	for i, s in ipairs(list) do
		ids[i] = {look = look, head = s.head, body = s.body, legs = s.legs, feet = s.feet, label = i .. " " .. tostring(s.name or "scheme")}
	end
	return G.layoutLooks(ids, origin)
end

-- The outfit of `wear <look> [scheme]` (scheme = number in the list; nil = the first one).
function G.wearOutfit(lib, look, scheme)
	local list = G.schemesOf(lib, look)
	local s = list[scheme or 1]
	if not s then return nil, "The look has " .. #list .. " scheme(s)." end
	return {lookType = look, lookHead = s.head or 0, lookBody = s.body or 0, lookLegs = s.legs or 0, lookFeet = s.feet or 0}
end

-- Effects: ids from..to (at most FX_MAX), one every FX_STEP_MS, cycling through 9 slots (3 columns 2 tiles apart, 3
-- rows 3 tiles apart, all inside the screen east of the admin) so a 2x2 effect has room. `known` maps effect id ->
-- {dx, dy, name} from ChaosVfx (optional).
function G.layoutFx(from, to, origin, known)
	local out = {}
	for i, id in ipairs(G.range(from, to, G.FX_MAX)) do
		local slot = (i - 1) % 9
		local col, row = slot % 3, floor(slot / 3)
		local k = (known or {})[id] or {}
		out[#out + 1] = {id = id, delay = (i - 1) * G.FX_STEP_MS, x = origin.x + G.OFFSET_X + col * 2 + (k.dx or 0),
			y = origin.y - 3 + row * 3 + (k.dy or 0), z = origin.z, name = k.name}
	end
	return out
end

-- Missiles: one lane each (6 lanes, cycling), from 1 tile east of the admin to 6 tiles east, one every FX_STEP_MS.
-- `ids` sorted ascending, unique.
function G.layoutMissiles(ids, origin)
	local out = {}
	for i, id in ipairs(ids or {}) do
		if i > G.FX_MAX then break end
		local y = origin.y - 2 + (i - 1) % 6
		out[#out + 1] = {id = id, delay = (i - 1) * G.FX_STEP_MS,
			from = {x = origin.x + 1, y = y, z = origin.z}, to = {x = origin.x + 6, y = y, z = origin.z}}
	end
	return out
end

-- Effect ids from a ChaosVfx-shaped table {name = {id=, dx=, dy=}}: id -> {name, dx, dy}
function G.knownFx(vfx)
	local out = {}
	for name, v in pairs(vfx or {}) do
		if type(v) == "table" and tonumber(v.id) and not out[v.id] then
			out[v.id] = {name = name, dx = v.dx or 0, dy = v.dy or 0}
		elseif type(v) == "table" and tonumber(v.id) and name < out[v.id].name then
			out[v.id] = {name = name, dx = v.dx or 0, dy = v.dy or 0}
		end
	end
	return out
end

-- Missile ids: the pair 30 ones (186-188) plus the ChaosVfxMissile table, unique and sorted.
function G.missileIds(missiles)
	local seen, out = {}, {}
	local function add(id) id = tonumber(id); if id and not seen[id] then seen[id] = true; out[#out + 1] = id end end
	add(186); add(187); add(188)
	for _, v in pairs(missiles or {}) do if type(v) == "table" then add(v.id) end end
	table.sort(out)
	return out
end

-- ------------------------------------------------------------------ what was placed, per admin
function G.newStore()
	return {byAdmin = {}}
end

-- records: list of {kind = "item"|"monster"|"ground", ...}; replaces nothing, a second call adds to the first.
function G.add(store, adminKey, records, now)
	local e = store.byAdmin[adminKey]
	if not e then e = {records = {}, at = now}; store.byAdmin[adminKey] = e end
	for _, r in ipairs(records) do e.records[#e.records + 1] = r end
	e.at = now
	return #e.records
end

-- takes everything of an admin out of the store (newest record first, so grounds restore in reverse order)
function G.take(store, adminKey)
	local e = store.byAdmin[adminKey]
	store.byAdmin[adminKey] = nil
	if not e then return {} end
	local out = {}
	for i = #e.records, 1, -1 do out[#out + 1] = e.records[i] end
	return out
end

-- admin keys whose last placement is older than TTL_MS
function G.expired(store, now)
	local out = {}
	for k, e in pairs(store.byAdmin) do
		if now - e.at >= G.TTL_MS then out[#out + 1] = k end
	end
	table.sort(out, function(a, b) return tostring(a) < tostring(b) end)
	return out
end

-- One log line per placed object: "id/key/name".
function G.line(p)
	return string.format("%s/%s/%s", tostring(p.id), tostring(p.key), tostring(p.name or ""))
end

return G
